INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z4-q68','nism-10b-z4','Monthly expenses are ₹15,000 today. With inflation of 7% p.a., the monthly expense after 11 years will be approximately:','["₹27,577","₹30,000","₹26,550","₹31,573"]',3,'Future expense = today''s expense × (1 + inflation)^n.',68) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z4-q69','nism-10b-z4','A goal of ₹35,00,000 is needed in 7 years. At 7% p.a. return, the lump sum to invest today is approximately:','["₹23,48,993","₹21,79,624","₹5,62,024","₹23,32,198"]',1,'PV = FV ÷ (1 + i)^n.',69) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z4-q70','nism-10b-z4','A client''s monthly essential expenses are ₹90,000. A 3-month emergency fund should be:','["₹10,80,000","₹2,70,000","₹5,40,000","₹1,35,000"]',1,'Emergency fund = months × monthly expenses.',70) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z4-q71','nism-10b-z4','₹9,50,000 is invested at 8% p.a. compounded annually for 9 years. The future value is approximately:','["₹20,50,979","₹18,99,054","₹17,58,384","₹16,34,000"]',1,'FV = P × (1 + i)^n.',71) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10b-z4-q72','nism-10b-z4','A loan of ₹22,00,000 at 12% p.a. for 5 years is repaid in monthly instalments. The EMI is approximately:','["₹36,667","₹58,667","₹48,938","₹56,278"]',2,'EMI = P·r·(1 + r)^n ÷ [(1 + r)^n − 1].',72) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort WHERE questions.quiz_id IS NOT excluded.quiz_id OR questions.question IS NOT excluded.question OR questions.options IS NOT excluded.options OR questions.answer IS NOT excluded.answer OR questions.explanation IS NOT excluded.explanation OR questions.sort IS NOT excluded.sort;
